import os as _o
def art(p): return f'''<article><header class="phero"><div class="w" style="max-width:820px"><div class="meta">{pmeta(p)}</div><h1 style="font-size:44px">{esc(p["title"])}</h1></div></header>
<section class="white"><div class="w prose" style="max-width:820px;font-size:18px">{f'<img src="{p["cover"]}" style="width:100%;border-radius:18px;margin-bottom:30px">' if p["cover"] else ''}{p["body"]}
<p style="margin-top:30px;font-size:13px;color:#7f90ab">{T("Nguồn","Source")}: <a href="{p["src"]}" target="_blank" rel="noopener">goealliance.org</a></p>
<div class="cta" style="margin-top:40px"><div><h3 style="font-size:22px">The Ledger Brief</h3><p style="color:#9fb0c6">{T("Nhận số tiếp theo","Get the next issue")}</p></div><a class="btn" href="ledger.html#brief">{T("Đăng ký","Subscribe")} →</a></div></div></section></article>'''
for p in BP:
  fn=f'blog/{p["slug"]}.html';page(fn,esc(p["title"])+' · GOE','blog.html',art(p))
