# --- 02/11: About us & Activities temporarily disabled (no URL)
import glob as _g, re as _re
_DIS='<a class="navoff" title="Sắp ra mắt · Coming soon" aria-disabled="true">\\2</a>'
for _f in _g.glob('*.html')+_g.glob('blog/*.html'):
  if _f in ('about.html','activities.html'): continue
  _h=open(_f).read()
  _h=_re.sub(r'<a href="(about|activities)\.html[^"]*"[^>]*>(.*?)</a>',_DIS,_h)
  _h=_h.replace('</style>','.navoff{cursor:default!important;opacity:.45}footer .navoff{display:block;padding:0;margin:0 0 8px}</style>',1)
  open(_f,'w').write(_h)
